// Pins the exact output of Intl for fr-CM / en-CM (checked on Node 20.19 with ICU 76 / CLDR 46). French groups digits with a narrow
// no-break space (U+202F) and puts a no-break space (U+00A0) before FCFA: a test that types a normal space fails.
// Generated by `eos scaffold i18n`. Run with Vitest (or adapt the imports to your test runner).
import { describe, expect, it } from "vitest";
import { formatDateTime, formatXaf, parseXafInput } from "./format";

const NNBSP = "\u202f";
const NBSP = "\u00a0";

describe("formatXaf", () => {
  it("formats French with narrow no-break spaces and FCFA after the amount", () => {
    expect(formatXaf(1234567, "fr")).toBe(`1${NNBSP}234${NNBSP}567${NBSP}FCFA`);
  });
  it("formats English with commas and FCFA before the amount", () => {
    expect(formatXaf(1234567, "en")).toBe(`FCFA${NBSP}1,234,567`);
  });
  it("has no decimals because XAF has no minor unit", () => {
    expect(formatXaf(500, "fr")).toBe(`500${NBSP}FCFA`);
  });
  it("rejects fractional francs instead of rounding silently", () => {
    expect(() => formatXaf(10.5, "fr")).toThrow(RangeError);
  });
});

describe("formatDateTime", () => {
  const d = new Date("2026-10-10T18:00:00Z"); // 19:00 in Douala (UTC+1)
  it("shows Douala time in French", () => {
    expect(formatDateTime(d, "fr")).toBe("10 octobre 2026 à 19:00");
  });
  it("shows Douala time in English", () => {
    expect(formatDateTime(d, "en")).toBe("10 October 2026 at 19:00");
  });
});

describe("parseXafInput", () => {
  it.each([
    ["1 234 567", 1234567],
    [`1${NNBSP}234${NNBSP}567${NBSP}FCFA`, 1234567],
    ["1,234,567", 1234567],
    ["1.234.567", 1234567],
    ["500", 500],
  ])("parses %s", (raw, want) => {
    expect(parseXafInput(raw)).toBe(want);
  });
  it.each(["", "abc", "-5", "12.5", "1,5", "1 23", "1e6"])("rejects %s", (raw) => {
    expect(parseXafInput(raw)).toBeNull();
  });
});
